1	import {createRequire} from 'module';
2	import type {ValidateFunction} from 'ajv';
3	import type {ToolDefinition} from '../../types/ai.js';
4	import type {OutgoingMessage} from '../../types/messages.js';
5	import {log} from '../../shared/logger.js';
6	
7	const require = createRequire(import.meta.url);
8	const Ajv = require('ajv');
9	
10	export interface ToolResponse {
11	  result: string;
12	  clientMessages?: OutgoingMessage[];
13	  suppressAssistantResponse?: boolean;
14	}
15	
16	export interface ToolContext {
17	  userId: string | number;
18	  sessionId?: string;
19	  workspaceId?: string | number;
20	  authHeaders?: {
21	    cookie?: string;
22	    authorization?: string;
23	    host?: string;
24	  };
25	}
26	
27	export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;
28	
29	export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
30	  return typeof response === 'string' ? {result: response} : response;
31	}
32	
33	export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);
34	
35	export interface RegisteredTool {
36	  definition: ToolDefinition;
37	  execute: ToolExecutor;
38	}
39	
40	interface StoredTool {
41	  definitionSource: ToolDefinitionSource;
42	  execute: ToolExecutor;
43	  validator: ValidateFunction;
44	}
45	
46	export class ToolRegistry {
47	  private readonly tools = new Map<string, StoredTool>();
48	  private readonly ajv = new Ajv({strict: false, validateFormats: false});
49	  private readonly functionValidatorCache = new WeakMap<Record<string, unknown>, ValidateFunction>();
50	
51	  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
52	    return typeof source === 'function' ? source() : source;
53	  }
54	
55	  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
56	    const resolved = this.resolveDefinition(definition);
57	
58	    if (typeof definition === 'function') {
59	      // For function-valued definitions, create a dummy validator that will be replaced at execute time
60	      const validator = (() => true) as unknown as ValidateFunction;
61	      this.tools.set(resolved.name, {definitionSource: definition, execute, validator});
62	      return;
63	    }
64	
65	    // For static definitions, compile the schema at register time
66	    try {
67	      const validator = this.ajv.compile(resolved.inputSchema);
68	      this.tools.set(resolved.name, {definitionSource: definition, execute, validator});
69	    } catch (error) {
70	      throw new Error(
71	        `Failed to compile inputSchema for tool '${resolved.name}': ${error instanceof Error ? error.message : String(error)}`,
72	        {
73	          cause: error,
74	        }
75	      );
76	    }
77	  }
78	
79	  get(name: string): RegisteredTool | undefined {
80	    const tool = this.tools.get(name);
81	    if (!tool) return undefined;
82	    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
83	  }
84	
85	  getDefinitions(): ToolDefinition[] {
86	    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
87	  }
88	
89	  getPromptInstructions(): string[] {
90	    return this.getDefinitions()
91	      .filter(t => t.promptInstructions)
92	      .map(t => `${t.name}: ${t.promptInstructions}`);
93	  }
94	
95	  getExamplePrompts(): string[] {
96	    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
97	  }
98	
99	  has(name: string): boolean {
100	    return this.tools.has(name);
101	  }
102	
103	  private buildErrorMessage(err: Record<string, unknown>): string {
104	    if (err.keyword === 'required') {
105	      const params = err.params as Record<string, string> | undefined;
106	      const missingProperty = params?.missingProperty ?? 'unknown';
107	      return `${missingProperty} is required`;
108	    }
109	
110	    if (err.keyword !== 'type') {
111	      return 'Validation failed';
112	    }
113	
114	    let fieldPath = String(err.instancePath ?? '').replace(/^\//, '');
115	    const schemaPath = String(err.schemaPath ?? '');
116	    const schemaMatch = schemaPath.match(/#\/properties\/([^/]+)/);
117	    fieldPath = fieldPath || schemaMatch?.[1] || 'unknown field';
118	    const params = err.params as Record<string, string> | undefined;
119	    const requiredType = params?.type ?? 'unknown type';
120	    return `${fieldPath} must be of type ${requiredType}`;
121	  }
122	
123	  /** Validate input against the registered tool's schema; on failure return a ToolResponse, on success invoke the executor ([specs/hal-engine-tool-input-validation](../../specs/hal-engine-tool-input-validation/spec.md)). */
124	  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
125	    const tool = this.tools.get(name);
126	    if (!tool) {
127	      log.warn('tool', 'tool not found', {name});
128	      throw new Error(`Unknown tool: ${name}`);
129	    }
130	
131	    // Get the current definition (may be different for function-valued sources)
132	    const definition = this.resolveDefinition(tool.definitionSource);
133	
134	    // Get or compile validator for this definition's schema
135	    let validator = tool.validator;
136	    if (typeof tool.definitionSource === 'function') {
137	      const cached = this.functionValidatorCache.get(definition.inputSchema as Record<string, unknown>);
138	      validator = cached ?? this.ajv.compile(definition.inputSchema);
139	      this.functionValidatorCache.set(definition.inputSchema as Record<string, unknown>, validator);
140	    }
141	
142	    // Validate input against schema
143	    if (!validator(input)) {
144	      const errors = (validator.errors ?? []) as unknown as Array<Record<string, unknown>>;
145	      const errorMessages = errors.map(err => this.buildErrorMessage(err));
146	      const result = errorMessages.join('; ');
147	      log.info('tool', 'schema validation failed', {name, errorCount: errors.length});
148	      return {result};
149	    }
150	
151	    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
